testWidgets('HUD and J key open a focus-safe met-only People journal', (
  tester,
) async {
  await tester.binding.setSurfaceSize(const Size(320, 480));
  addTearDown(() => tester.binding.setSurfaceSize(null));
  await _pumpGame(tester);
  final game = _game(tester);

  await tester.tap(find.byKey(InventoryHudOverlay.peopleButtonKey));
  await tester.pump();

  expect(game.overlays.isActive(GameOverlayIds.people), isTrue);
  expect(game.isGameplayInputLocked, isTrue);
  expect(find.byKey(PeopleJournalOverlay.emptyKey), findsOneWidget);
  expect(tester.takeException(), isNull);

  await tester.tap(find.byKey(PeopleJournalOverlay.closeButtonKey));
  await tester.pump();
  expect(game.isGameplayInputLocked, isFalse);
  expect(_gameFocusNode(tester).hasFocus, isTrue);

  await tester.sendKeyEvent(LogicalKeyboardKey.keyJ);
  await tester.pump();
  expect(game.overlays.isActive(GameOverlayIds.people), isTrue);
  await tester.sendKeyEvent(LogicalKeyboardKey.keyJ);
  await tester.pump();
  expect(game.overlays.isActive(GameOverlayIds.people), isFalse);
});

testWidgets('dialogue profile shows learned fact and hides unknown facts', (
  tester,
) async {
  await tester.binding.setSurfaceSize(const Size(1280, 720));
  addTearDown(() => tester.binding.setSurfaceSize(null));
  await _pumpGame(tester);
  final game = _game(tester);

  expect(
    game.tryCollectResourceNode(
      nodeId: 'journal-moonflower',
      resourceId: 'moonflower',
    ),
    isTrue,
  );
  game.openDialogueForNpc('npc-01');
  await tester.pump();
  await tester.tap(
    find.byKey(
      DialogueOverlay.choiceButtonKey(Npc01DialogueIds.npc01NeutralChoiceId),
    ),
  );
  await tester.pump();
  game.closeDialogue();
  await tester.pump();
  game.openDialogueForNpc('npc-01');
  await tester.pump();
  expect(game.activeDialogue!.id, 'npc-01-moonflower-hint');

  await tester.tap(find.byKey(DialogueOverlay.profileButtonKey));
  await tester.pump();

  expect(game.overlays.isActive(GameOverlayIds.dialogue), isFalse);
  expect(game.overlays.isActive(GameOverlayIds.people), isTrue);
  expect(
    find.bySemanticsLabel('Profile for Mayor Edric Vale'),
    findsOneWidget,
  );
  expect(find.text('Mayor Edric Vale'), findsNWidgets(2));
  expect(find.text('Moonflowers'), findsOneWidget);
  expect(
    find.text('Edric has a particular fondness for Moonflowers.'),
    findsOneWidget,
  );
  expect(find.text('Town mayor'), findsNothing);
  expect(find.textContaining('reelection'), findsNothing);
  final portraitFinder = find.byType(Image);
  expect(portraitFinder, findsOneWidget);
  final portrait = tester.widget<Image>(portraitFinder);
  expect(portrait.filterQuality, FilterQuality.high);
  expect(portrait.isAntiAlias, isTrue);
  expect(tester.takeException(), isNull);
});

testWidgets('Helena profile uses clean-HD official portrait', (tester) async {
  await tester.binding.setSurfaceSize(const Size(1280, 720));
  addTearDown(() => tester.binding.setSurfaceSize(null));
  await _pumpGame(tester);
  final game = _game(tester);

  game.openDialogueForNpc('npc-02');
  await tester.pump();
  await tester.tap(find.byKey(DialogueOverlay.profileButtonKey));
  await tester.pump();

  expect(find.bySemanticsLabel('Profile for Helena Vale'), findsOneWidget);
  expect(find.bySemanticsLabel('Portrait of Helena Vale'), findsOneWidget);
  final portraitFinder = find.byType(Image);
  expect(portraitFinder, findsOneWidget);
  final portrait = tester.widget<Image>(portraitFinder);
  expect(
    (portrait.image as AssetImage).assetName,
    'assets/images/portraits/npc-02/official-neutral.png',
  );
  expect(portrait.filterQuality, FilterQuality.high);
  expect(portrait.isAntiAlias, isTrue);
  expect(tester.getSize(portraitFinder), const Size.square(240));
  expect(tester.takeException(), isNull);
});
